-- ----------------------------
-- Table structure for eb_agent_level
-- ----------------------------
DROP TABLE IF EXISTS `eb_agent_level`;
CREATE TABLE `eb_agent_level`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '等级名称',
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '背景图',
  `color` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT ' 字体颜色',
  `one_brokerage` smallint(5) NOT NULL DEFAULT 0 COMMENT '一级分拥比例',
  `two_brokerage` smallint(5) NOT NULL DEFAULT 0 COMMENT '二级分拥比例',
  `grade` smallint(5) NOT NULL DEFAULT 0 COMMENT '等级',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态',
  `is_del` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否删除',
  `add_time` int(10) NOT NULL DEFAULT 0 COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`, `is_del`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销员等级表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of eb_agent_level
-- ----------------------------

-- ----------------------------
-- Table structure for eb_agent_level_task
-- ----------------------------
DROP TABLE IF EXISTS `eb_agent_level_task`;
CREATE TABLE `eb_agent_level_task`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `level_id` int(10) NOT NULL DEFAULT 0 COMMENT '分销等级id',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '任务名称',
  `type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '任务类型',
  `number` int(10) NOT NULL DEFAULT 0 COMMENT '任务限定数',
  `desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '任务描述',
  `is_must` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否必须达成0:其一1:所有',
  `sort` smallint(5) NOT NULL DEFAULT 0 COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态',
  `is_del` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否删除',
  `add_time` int(10) NOT NULL DEFAULT 0 COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销员等级任务表' ROW_FORMAT = Dynamic;

