-- ----------------------------
-- Table structure for eb_agreement
-- ----------------------------
DROP TABLE IF EXISTS `eb_agreement`;
CREATE TABLE `eb_agreement`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '协议类型  1：会员协议',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '协议名称',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '协议内容',
  `sort` int(10) NOT NULL DEFAULT 0 COMMENT '排序倒序',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT 1 COMMENT '1：显示：0：不显示',
  `add_time` int(50) NOT NULL DEFAULT 0 COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `type`(`type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会员协议' ROW_FORMAT = Dynamic;

