-- ----------------------------
-- Table structure for eb_card_batch
-- ----------------------------
DROP TABLE IF EXISTS `eb_card_batch`;
CREATE TABLE `eb_card_batch`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '卡次名称',
  `card_prefix` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '卡号前缀',
  `card_suffix` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '卡号后缀',
  `prefix` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '卡号前缀+后缀',
  `total_num` int(11) NOT NULL DEFAULT 0 COMMENT '总数量',
  `used_num` int(11) NOT NULL DEFAULT 0 COMMENT '使用数量',
  `add_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `is_del` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否删除 0-正常 1-已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '卡次表' ROW_FORMAT = Dynamic;

