-- Table structure for eb_card_gift_auxiliary
-- ----------------------------
DROP TABLE IF EXISTS `eb_card_gift_auxiliary`;
CREATE TABLE `eb_card_gift_auxiliary`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `gift_id` int(11) NOT NULL DEFAULT 0,
  `product_id` int(11) NOT NULL DEFAULT 0,
  `limit_num` int(11) NOT NULL DEFAULT 0 COMMENT '赠送个数',
  `unique` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品unique',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '兑换卡商品辅助表' ROW_FORMAT = Dynamic;

