INSERT INTO `eb_cache` VALUES ('user', '\"<h2><b>\\u4e00\\u3001\\u534f\\u8bae\\u76ee\\u7684\\u4e0e\\u4f9d\\u636e<\\/b><b><\\/b><\\/h2><p>1.1 \\u4e3a\\u89c4\\u8303 [\\u4e2d\\u519c\\u666e\\u60e0\\u6613\\u8d27\\u7f51]\\uff0c\\u7b80\\u79f0[\\u6613\\u8d27\\u7f51]\\u6ce8\\u518c\\u7f51\\u5740\\uff1a[www.yuyegongshe.cn]\\uff09\\u4f1a\\u5458\\u6ce8\\u518c\\u3001\\u4f7f\\u7528\\u7b49\\u76f8\\u5173\\u884c\\u4e3a\\uff0c\\u660e\\u786e\\u6613\\u8d27\\u7f51\\u4e0e\\u4f1a\\u5458\\u4e4b\\u95f4\\u7684\\u6743\\u5229\\u4e49\\u52a1\\u5173\\u7cfb\\uff0c\\u4fdd\\u62a4\\u53cc\\u65b9\\u5408\\u6cd5\\u6743\\u76ca\\uff0c\\u4f9d\\u636e\\u300a\\u4e2d\\u534e\\u4eba\\u6c11\\u5171\\u548c\\u56fd\\u6c11\\u6cd5\\u5178\\u300b\\u300a\\u4e2d\\u534e\\u4eba\\u6c11\\u5171\\u548c\\u56fd\\u7535\\u5b50\\u5546\\u52a1\\u6cd5\\u300b\\u300a\\u4e2d\\u534e\\u4eba\\u6c11\\u5171\\u548c\\u56fd\\u4e2a\\u4eba\\u4fe1\\u606f\\u4fdd\\u62a4\\u6cd5\\u300b\\u7b49\\u76f8\\u5173\\u6cd5\\u5f8b\\u6cd5\\u89c4\\uff0c\\u5236\\u5b9a\\u672c\\u534f\\u8bae\\u3002<\\/p><p>1.2 \\u672c\\u534f\\u8bae\\u662f\\u6613\\u8d27\\u7f51\\u4e0e\\u4f1a\\u5458\\u4e4b\\u95f4\\u5c31\\u4f1a\\u5458\\u6ce8\\u518c\\u3001\\u4f7f\\u7528\\u6613\\u8d27\\u7f51\\u670d\\u52a1\\u6240\\u8fbe\\u6210\\u7684\\u5177\\u6709\\u6cd5\\u5f8b\\u6548\\u529b\\u7684\\u534f\\u8bae\\u3002\\u4f1a\\u5458\\u5728\\u7533\\u8bf7\\u6ce8\\u518c\\u6613\\u8d27\\u7f51\\u4f1a\\u5458\\u524d\\uff0c\\u5e94\\u4ed4\\u7ec6\\u9605\\u8bfb\\u5e76\\u5145\\u5206\\u7406\\u89e3\\u672c\\u534f\\u8bae\\u5168\\u90e8\\u6761\\u6b3e\\uff0c\\u7279\\u522b\\u662f\\u6d89\\u53ca\\u4f1a\\u5458\\u6743\\u5229\\u4e49\\u52a1\\u3001\\u8d23\\u4efb\\u9650\\u5236\\u3001\\u514d\\u8d23\\u6761\\u6b3e\\u7b49\\u5185\\u5bb9\\u3002\\u4f1a\\u5458\\u70b9\\u51fb \\u201c\\u540c\\u610f\\u6ce8\\u518c\\u201d \\u6216\\u5b8c\\u6210\\u6ce8\\u518c\\u6d41\\u7a0b\\uff0c\\u5373\\u89c6\\u4e3a\\u5df2\\u5b8c\\u5168\\u7406\\u89e3\\u5e76\\u63a5\\u53d7\\u672c\\u534f\\u8bae\\u5168\\u90e8\\u6761\\u6b3e\\uff0c\\u81ea\\u613f\\u4e0e\\u6613\\u8d27\\u7f51\\u5efa\\u7acb\\u4f1a\\u5458\\u670d\\u52a1\\u5173\\u7cfb\\u3002<\\/p><h2><b>\\u4e8c\\u3001\\u4f1a\\u5458\\u8d44\\u683c<\\/b><b><\\/b><\\/h2><p>2.1 \\u5e74\\u6ee1 18 \\u5468\\u5c81\\uff0c\\u5177\\u6709\\u5b8c\\u5168\\u6c11\\u4e8b\\u884c\\u4e3a\\u80fd\\u529b\\u7684\\u81ea\\u7136\\u4eba\\uff0c\\u6216\\u4f9d\\u6cd5\\u8bbe\\u7acb\\u5e76\\u6709\\u6548\\u5b58\\u7eed\\u7684\\u6cd5\\u4eba\\u3001\\u5176\\u4ed6\\u7ec4\\u7ec7\\uff0c\\u53ef\\u7533\\u8bf7\\u6210\\u4e3a\\u6613\\u8d27\\u7f51\\u4f1a\\u5458\\u3002<\\/p><p>2.2 \\u672a\\u6210\\u5e74\\u4eba\\u7533\\u8bf7\\u6ce8\\u518c\\u4f1a\\u5458\\uff0c\\u987b\\u5728\\u5176\\u6cd5\\u5b9a\\u76d1\\u62a4\\u4eba\\u7684\\u966a\\u540c\\u4e0b\\uff0c\\u7531\\u6cd5\\u5b9a\\u76d1\\u62a4\\u4eba\\u4ee3\\u4e3a\\u5b8c\\u6210\\u6ce8\\u518c\\uff0c\\u5e76\\u7531\\u6cd5\\u5b9a\\u76d1\\u62a4\\u4eba\\u5bf9\\u5176\\u4f7f\\u7528\\u6613\\u8d27\\u7f51\\u670d\\u52a1\\u7684\\u884c\\u4e3a\\u627f\\u62c5\\u5168\\u90e8\\u8d23\\u4efb\\u3002<\\/p><p>2.3 \\u6709\\u4e0b\\u5217\\u60c5\\u5f62\\u4e4b\\u4e00\\u7684\\uff0c\\u4e0d\\u5f97\\u7533\\u8bf7\\u6210\\u4e3a\\u6613\\u8d27\\u7f51\\u4f1a\\u5458\\uff0c\\u5df2\\u6ce8\\u518c\\u4f1a\\u5458\\u7684\\uff0c\\u6613\\u8d27\\u7f51\\u6709\\u6743\\u53d6\\u6d88\\u5176\\u4f1a\\u5458\\u8d44\\u683c\\uff1a<\\/p><p>\\uff081\\uff09\\u65e0\\u6c11\\u4e8b\\u884c\\u4e3a\\u80fd\\u529b\\u4eba\\u6216\\u9650\\u5236\\u6c11\\u4e8b\\u884c\\u4e3a\\u80fd\\u529b\\u4eba\\u4e14\\u672a\\u53d6\\u5f97\\u6cd5\\u5b9a\\u76d1\\u62a4\\u4eba\\u540c\\u610f\\u7684\\uff1b<\\/p><p>\\uff082\\uff09\\u66fe\\u56e0\\u8fdd\\u53cd\\u672c\\u534f\\u8bae\\u6216\\u6613\\u8d27\\u7f51\\u5176\\u4ed6\\u89c4\\u5219\\uff0c\\u88ab\\u6613\\u8d27\\u7f51\\u53d6\\u6d88\\u4f1a\\u5458\\u8d44\\u683c\\u4e14\\u5904\\u4e8e\\u9650\\u5236\\u6ce8\\u518c\\u671f\\u9650\\u5185\\u7684\\uff1b<\\/p><p>\\uff083\\uff09\\u88ab\\u4eba\\u6c11\\u6cd5\\u9662\\u5217\\u4e3a\\u5931\\u4fe1\\u88ab\\u6267\\u884c\\u4eba\\u7684\\uff1b<\\/p><p>\\uff084\\uff09\\u6cd5\\u5f8b\\u6cd5\\u89c4\\u89c4\\u5b9a\\u4e0d\\u5f97\\u4ece\\u4e8b\\u7535\\u5b50\\u5546\\u52a1\\u6d3b\\u52a8\\u7684\\u5176\\u4ed6\\u60c5\\u5f62\\u3002<\\/p><h2><b>\\u4e09\\u3001\\u4f1a\\u5458\\u6ce8\\u518c\\u4e0e\\u8d26\\u53f7\\u7ba1\\u7406<\\/b><b><\\/b><\\/h2><p>3.1 \\u4f1a\\u5458\\u6ce8\\u518c\\u65f6\\uff0c\\u5e94\\u6309\\u7167\\u6613\\u8d27\\u7f51\\u6ce8\\u518c\\u9875\\u9762\\u7684\\u8981\\u6c42\\uff0c\\u63d0\\u4f9b\\u771f\\u5b9e\\u3001\\u51c6\\u786e\\u3001\\u5b8c\\u6574\\u3001\\u6709\\u6548\\u7684\\u4e2a\\u4eba\\u6216\\u5355\\u4f4d\\u4fe1\\u606f\\uff08\\u5305\\u62ec\\u4f46\\u4e0d\\u9650\\u4e8e\\u59d3\\u540d \\/ \\u540d\\u79f0\\u3001\\u8eab\\u4efd\\u8bc1\\u53f7\\u7801 \\/ \\u7edf\\u4e00\\u793e\\u4f1a\\u4fe1\\u7528\\u4ee3\\u7801\\u3001\\u8054\\u7cfb\\u65b9\\u5f0f\\u3001\\u5730\\u5740\\u7b49\\uff09\\uff0c\\u5e76\\u5bf9\\u6240\\u63d0\\u4f9b\\u4fe1\\u606f\\u7684\\u771f\\u5b9e\\u6027\\u3001\\u5408\\u6cd5\\u6027\\u3001\\u6709\\u6548\\u6027\\u627f\\u62c5\\u5168\\u90e8\\u8d23\\u4efb\\u3002<\\/p><p>3.2 \\u6613\\u8d27\\u7f51\\u5c06\\u5bf9\\u4f1a\\u5458\\u63d0\\u4ea4\\u7684\\u6ce8\\u518c\\u4fe1\\u606f\\u8fdb\\u884c\\u5ba1\\u6838\\uff0c\\u5ba1\\u6838\\u901a\\u8fc7\\u540e\\uff0c\\u4f1a\\u5458\\u8d26\\u53f7\\u6b63\\u5f0f\\u5f00\\u901a\\u3002\\u4f1a\\u5458\\u8d26\\u53f7\\u7531\\u4f1a\\u5458\\u81ea\\u884c\\u8bbe\\u7f6e\\u7684\\u7528\\u6237\\u540d\\uff08\\u6216\\u624b\\u673a\\u53f7\\u7801 \\/ \\u90ae\\u7bb1\\u5730\\u5740\\uff09\\u548c\\u5bc6\\u7801\\u7ec4\\u6210\\uff0c\\u4f1a\\u5458\\u5e94\\u59a5\\u5584\\u4fdd\\u7ba1\\u8d26\\u53f7\\u53ca\\u5bc6\\u7801\\uff0c\\u4e0d\\u5f97\\u5c06\\u8d26\\u53f7\\u3001\\u5bc6\\u7801\\u51fa\\u501f\\u3001\\u8f6c\\u8ba9\\u7ed9\\u4ed6\\u4eba\\u4f7f\\u7528\\u3002\\u56e0\\u4f1a\\u5458\\u81ea\\u8eab\\u539f\\u56e0\\u5bfc\\u81f4\\u8d26\\u53f7\\u3001\\u5bc6\\u7801\\u6cc4\\u9732\\u6216\\u88ab\\u4ed6\\u4eba\\u76d7\\u7528\\u6240\\u4ea7\\u751f\\u7684\\u4e00\\u5207\\u635f\\u5931\\u548c\\u6cd5\\u5f8b\\u8d23\\u4efb\\uff0c\\u7531\\u4f1a\\u5458\\u81ea\\u884c\\u627f\\u62c5\\u3002<\\/p><p>3.3 \\u4f1a\\u5458\\u53d1\\u73b0\\u8d26\\u53f7\\u88ab\\u76d7\\u7528\\u6216\\u5b58\\u5728\\u5f02\\u5e38\\u4f7f\\u7528\\u60c5\\u51b5\\u7684\\uff0c\\u5e94\\u7acb\\u5373\\u901a\\u77e5\\u6613\\u8d27\\u7f51\\u5ba2\\u670d\\uff08\\u5ba2\\u670d\\u7535\\u8bdd\\uff1a[18877872689]\\uff0c\\u5ba2\\u670d\\u90ae\\u7bb1\\uff1a[puhuiyihuo@163.com]\\uff09\\uff0c\\u5e76\\u914d\\u5408\\u6613\\u8d27\\u7f51\\u91c7\\u53d6\\u51bb\\u7ed3\\u8d26\\u53f7\\u3001\\u4fee\\u6539\\u5bc6\\u7801\\u7b49\\u63aa\\u65bd\\u3002\\u5546\\u57ce\\u5728\\u6536\\u5230\\u4f1a\\u5458\\u901a\\u77e5\\u5e76\\u6838\\u5b9e\\u76f8\\u5173\\u60c5\\u51b5\\u540e\\uff0c\\u5c06\\u53ca\\u65f6\\u91c7\\u53d6\\u76f8\\u5e94\\u63aa\\u65bd\\uff0c\\u4f46\\u56e0\\u4f1a\\u5458\\u672a\\u53ca\\u65f6\\u901a\\u77e5\\u6216\\u672a\\u914d\\u5408\\u5546\\u57ce\\u91c7\\u53d6\\u63aa\\u65bd\\u5bfc\\u81f4\\u635f\\u5931\\u6269\\u5927\\u7684\\uff0c\\u6269\\u5927\\u90e8\\u5206\\u7684\\u635f\\u5931\\u7531\\u4f1a\\u5458\\u81ea\\u884c\\u627f\\u62c5\\u3002<\\/p><p>3.4 \\u4f1a\\u5458\\u4fe1\\u606f\\u53d1\\u751f\\u53d8\\u66f4\\u7684\\uff0c\\u5e94\\u53ca\\u65f6\\u767b\\u5f55\\u6613\\u8d27\\u7f51\\u8d26\\u53f7\\u5728 \\u201c\\u4e2a\\u4eba\\u4e2d\\u5fc3\\u201d \\u6216\\u76f8\\u5173\\u9875\\u9762\\u66f4\\u65b0\\u4fe1\\u606f\\u3002\\u56e0\\u4f1a\\u5458\\u672a\\u53ca\\u65f6\\u66f4\\u65b0\\u4fe1\\u606f\\u5bfc\\u81f4\\u6613\\u8d27\\u7f51\\u65e0\\u6cd5\\u6b63\\u5e38\\u63d0\\u4f9b\\u670d\\u52a1\\u3001\\u65e0\\u6cd5\\u9001\\u8fbe\\u76f8\\u5173\\u901a\\u77e5\\u6216\\u4ea7\\u751f\\u5176\\u4ed6\\u635f\\u5931\\u7684\\uff0c\\u7531\\u4f1a\\u5458\\u81ea\\u884c\\u627f\\u62c5\\u8d23\\u4efb\\u3002<\\/p><h2><b>\\u56db\\u3001\\u4f1a\\u5458\\u6743\\u5229<\\/b><b><\\/b><\\/h2><p>4.1 \\u4f1a\\u5458\\u6709\\u6743\\u767b\\u5f55\\u6613\\u8d27\\u7f51\\u8d26\\u53f7\\uff0c\\u6d4f\\u89c8\\u5546\\u57ce\\u5c55\\u793a\\u7684\\u5546\\u54c1\\u4fe1\\u606f\\u3001\\u670d\\u52a1\\u5185\\u5bb9\\uff0c\\u67e5\\u8be2\\u5546\\u54c1\\u4ef7\\u683c\\u3001\\u89c4\\u683c\\u3001\\u5e93\\u5b58\\u7b49\\u76f8\\u5173\\u4fe1\\u606f\\u3002<\\/p><p>4.2 \\u4f1a\\u5458\\u6709\\u6743\\u6839\\u636e\\u5546\\u57ce\\u89c4\\u5219\\u53ca\\u5b9e\\u9645\\u9700\\u6c42\\uff0c\\u5728\\u5546\\u57ce\\u8d2d\\u4e70\\u5546\\u54c1\\u6216\\u63a5\\u53d7\\u670d\\u52a1\\uff0c\\u53c2\\u4e0e\\u5546\\u57ce\\u7ec4\\u7ec7\\u7684\\u4fc3\\u9500\\u6d3b\\u52a8\\u3001\\u4f1a\\u5458\\u798f\\u5229\\u6d3b\\u52a8\\u7b49\\u3002<\\/p><p>4.3 \\u4f1a\\u5458\\u6709\\u6743\\u5bf9\\u8d2d\\u4e70\\u7684\\u5546\\u54c1\\u6216\\u63a5\\u53d7\\u7684\\u670d\\u52a1\\u8fdb\\u884c\\u8bc4\\u4ef7\\u3001\\u6295\\u8bc9\\u3001\\u5efa\\u8bae\\uff0c\\u6613\\u8d27\\u7f51\\u5e94\\u6309\\u7167\\u76f8\\u5173\\u89c4\\u5219\\u53ca\\u65f6\\u5904\\u7406\\u4f1a\\u5458\\u7684\\u5408\\u7406\\u8bc9\\u6c42\\u3002<\\/p><p>4.4 \\u4f1a\\u5458\\u6709\\u6743\\u67e5\\u8be2\\u81ea\\u5df1\\u7684\\u4f1a\\u5458\\u8d26\\u53f7\\u4fe1\\u606f\\u3001\\u8ba2\\u5355\\u8bb0\\u5f55\\u3001\\u6d88\\u8d39\\u8bb0\\u5f55\\u3001\\u79ef\\u5206\\u60c5\\u51b5\\uff08\\u5982\\u6709\\uff09\\u7b49\\u4e2a\\u4eba\\u4ea4\\u6613\\u76f8\\u5173\\u4fe1\\u606f\\u3002<\\/p><p>4.5 \\u4f1a\\u5458\\u6709\\u6743\\u6839\\u636e\\u672c\\u534f\\u8bae\\u7ea6\\u5b9a\\uff0c\\u7533\\u8bf7\\u6ce8\\u9500\\u4f1a\\u5458\\u8d26\\u53f7\\uff0c\\u6613\\u8d27\\u7f51\\u5e94\\u5728\\u6838\\u5b9e\\u4f1a\\u5458\\u8eab\\u4efd\\u5e76\\u5904\\u7406\\u5b8c\\u76f8\\u5173\\u4e8b\\u5b9c\\u540e\\uff0c\\u4e3a\\u4f1a\\u5458\\u529e\\u7406\\u8d26\\u53f7\\u6ce8\\u9500\\u624b\\u7eed\\u3002<\\/p><p>4.6 \\u6cd5\\u5f8b\\u6cd5\\u89c4\\u53ca\\u672c\\u534f\\u8bae\\u7ea6\\u5b9a\\u7684\\u5176\\u4ed6\\u6743\\u5229\\u3002<\\/p><h2><b>\\u4e94\\u3001\\u4f1a\\u5458\\u4e49\\u52a1<\\/b><b><\\/b><\\/h2><p>5.1 \\u4f1a\\u5458\\u5e94\\u9075\\u5b88\\u56fd\\u5bb6\\u6cd5\\u5f8b\\u6cd5\\u89c4\\u53ca\\u76f8\\u5173\\u653f\\u7b56\\u89c4\\u5b9a\\uff0c\\u9075\\u5b88\\u793e\\u4f1a\\u516c\\u5fb7\\u548c\\u5546\\u4e1a\\u9053\\u5fb7\\uff0c\\u4e0d\\u5f97\\u5229\\u7528\\u6613\\u8d27\\u7f51\\u8d26\\u53f7\\u4ece\\u4e8b\\u4efb\\u4f55\\u8fdd\\u6cd5\\u8fdd\\u89c4\\u6d3b\\u52a8\\uff0c\\u4e0d\\u5f97\\u635f\\u5bb3\\u6613\\u8d27\\u7f51\\u53ca\\u5176\\u4ed6\\u4f1a\\u5458\\u3001\\u7b2c\\u4e09\\u65b9\\u7684\\u5408\\u6cd5\\u6743\\u76ca\\u3002<\\/p><p>5.2 \\u4f1a\\u5458\\u5e94\\u9075\\u5b88\\u6613\\u8d27\\u7f51\\u53d1\\u5e03\\u7684\\u5404\\u9879\\u89c4\\u5219\\u3001\\u516c\\u544a\\u3001\\u901a\\u77e5\\u7b49\\uff08\\u5305\\u62ec\\u4f46\\u4e0d\\u9650\\u4e8e\\u8d2d\\u7269\\u89c4\\u5219\\u3001\\u552e\\u540e\\u89c4\\u5219\\u3001\\u9690\\u79c1\\u653f\\u7b56\\u7b49\\uff09\\uff0c\\u5982\\u6709\\u51b2\\u7a81\\uff0c\\u4ee5\\u672c\\u534f\\u8bae\\u4e3a\\u51c6\\uff1b\\u672c\\u534f\\u8bae\\u672a\\u7ea6\\u5b9a\\u7684\\uff0c\\u4ee5\\u6613\\u8d27\\u7f51\\u4e3a\\u51c6<\\/p><p>5.3 \\u4f1a\\u5458\\u5728\\u4f7f\\u7528\\u6613\\u8d27\\u7f51\\u670d\\u52a1\\u8fc7\\u7a0b\\u4e2d\\uff0c\\u5e94\\u4fdd\\u8bc1\\u6240\\u53d1\\u5e03\\u7684\\u4fe1\\u606f\\u3001\\u8a00\\u8bba\\u7b49\\u5185\\u5bb9\\u771f\\u5b9e\\u3001\\u5408\\u6cd5\\u3001\\u6709\\u6548\\uff0c\\u4e0d\\u5f97\\u542b\\u6709\\u4e0b\\u5217\\u5185\\u5bb9\\uff1a<\\/p><p>\\uff081\\uff09\\u8fdd\\u53cd\\u56fd\\u5bb6\\u6cd5\\u5f8b\\u6cd5\\u89c4\\u53ca\\u653f\\u7b56\\u89c4\\u5b9a\\u7684\\uff1b<\\/p><p>\\uff082\\uff09\\u635f\\u5bb3\\u56fd\\u5bb6\\u5229\\u76ca\\u3001\\u793e\\u4f1a\\u516c\\u5171\\u5229\\u76ca\\uff0c\\u7834\\u574f\\u6c11\\u65cf\\u56e2\\u7ed3\\u548c\\u793e\\u4f1a\\u7a33\\u5b9a\\u7684\\uff1b<\\/p><p>\\uff083\\uff09\\u542b\\u6709\\u6deb\\u79fd\\u3001\\u8272\\u60c5\\u3001\\u8d4c\\u535a\\u3001\\u66b4\\u529b\\u3001\\u6050\\u6016\\u3001\\u4fae\\u8fb1\\u3001\\u8bfd\\u8c24\\u3001\\u6b3a\\u8bc8\\u7b49\\u8fdd\\u6cd5\\u6216\\u8fdd\\u80cc\\u516c\\u5e8f\\u826f\\u4fd7\\u5185\\u5bb9\\u7684\\uff1b<\\/p><p>\\uff084\\uff09\\u4fb5\\u72af\\u4ed6\\u4eba\\u77e5\\u8bc6\\u4ea7\\u6743\\u3001\\u8096\\u50cf\\u6743\\u3001\\u9690\\u79c1\\u6743\\u3001\\u540d\\u8a89\\u6743\\u7b49\\u5408\\u6cd5\\u6743\\u76ca\\u7684\\uff1b<\\/p><p>\\uff085\\uff09\\u542b\\u6709\\u75c5\\u6bd2\\u3001\\u6728\\u9a6c\\u7b49\\u6076\\u610f\\u7a0b\\u5e8f\\u6216\\u5176\\u4ed6\\u53ef\\u80fd\\u5371\\u5bb3\\u6613\\u8d27\\u7f51\\u7cfb\\u7edf\\u5b89\\u5168\\u3001\\u5f71\\u54cd\\u5176\\u4ed6\\u4f1a\\u5458\\u6b63\\u5e38\\u4f7f\\u7528\\u7684\\u5185\\u5bb9\\uff1b<\\/p><p>\\uff086\\uff09\\u5176\\u4ed6\\u8fdd\\u53cd\\u6cd5\\u5f8b\\u6cd5\\u89c4\\u3001\\u793e\\u4f1a\\u516c\\u5fb7\\u6216\\u6613\\u8d27\\u7f51\\u89c4\\u5219\\u7684\\u5185\\u5bb9\\u3002<\\/p><p>5.4 \\u4f1a\\u5458\\u5e94\\u6309\\u7167\\u6613\\u8d27\\u7f51\\u89c4\\u5b9a\\u53ca\\u8ba2\\u5355\\u7ea6\\u5b9a\\uff0c\\u53ca\\u65f6\\u652f\\u4ed8\\u5546\\u54c1\\u4ef7\\u6b3e\\u3001\\u8fd0\\u8d39\\uff08\\u5982\\u6709\\uff09\\u7b49\\u76f8\\u5173\\u8d39\\u7528\\u3002\\u5982\\u4f1a\\u5458\\u672a\\u6309\\u65f6\\u652f\\u4ed8\\u8d39\\u7528\\uff0c\\u6613\\u8d27\\u7f51\\u6709\\u6743\\u53d6\\u6d88\\u8ba2\\u5355\\uff0c\\u5e76\\u8ffd\\u7a76\\u4f1a\\u5458\\u7684\\u8fdd\\u7ea6\\u8d23\\u4efb\\u3002<\\/p><p>5.5 \\u4f1a\\u5458\\u5728\\u6536\\u5230\\u5546\\u54c1\\u540e\\uff0c\\u5e94\\u53ca\\u65f6\\u67e5\\u9a8c\\u5546\\u54c1\\u7684\\u6570\\u91cf\\u3001\\u89c4\\u683c\\u3001\\u8d28\\u91cf\\u7b49\\u662f\\u5426\\u7b26\\u5408\\u8ba2\\u5355\\u7ea6\\u5b9a\\u3002\\u5982\\u53d1\\u73b0\\u5546\\u54c1\\u5b58\\u5728\\u95ee\\u9898\\uff0c\\u5e94\\u6309\\u7167\\u6613\\u8d27\\u7f51\\u552e\\u540e\\u89c4\\u5219\\u53ca\\u65f6\\u4e0e\\u6613\\u8d27\\u7f51\\u6c9f\\u901a\\u5904\\u7406\\uff0c\\u4e0d\\u5f97\\u64c5\\u81ea\\u635f\\u574f\\u3001\\u4e22\\u5f03\\u5546\\u54c1\\u6216\\u62d2\\u7edd\\u914d\\u5408\\u6613\\u8d27\\u7f51\\u8fdb\\u884c\\u552e\\u540e\\u6838\\u67e5\\u3002<\\/p><p>5.6 \\u4f1a\\u5458\\u4e0d\\u5f97\\u5229\\u7528\\u6613\\u8d27\\u7f51\\u670d\\u52a1\\u4ece\\u4e8b\\u4e0b\\u5217\\u4e0d\\u6b63\\u5f53\\u7ade\\u4e89\\u6216\\u6270\\u4e71\\u5e02\\u573a\\u79e9\\u5e8f\\u7684\\u884c\\u4e3a\\uff1a<\\/p><p>\\uff081\\uff09\\u865a\\u5047\\u4ea4\\u6613\\u3001\\u5237\\u5355\\u7092\\u4fe1\\u3001\\u9a97\\u53d6\\u79ef\\u5206\\u6216\\u4f18\\u60e0\\u6743\\u76ca\\u7b49\\uff1b<\\/p><p>\\uff082\\uff09\\u6076\\u610f\\u5dee\\u8bc4\\u3001\\u8bcb\\u6bc1\\u7ade\\u4e89\\u5bf9\\u624b\\u3001\\u6270\\u4e71\\u5546\\u57ce\\u6b63\\u5e38\\u7ecf\\u8425\\u79e9\\u5e8f\\u7684\\uff1b<\\/p><p>\\uff083\\uff09\\u672a\\u7ecf\\u6613\\u8d27\\u7f51\\u8bb8\\u53ef\\uff0c\\u64c5\\u81ea\\u4f7f\\u7528\\u6613\\u8d27\\u7f51\\u7684\\u5546\\u6807\\u3001\\u6807\\u8bc6\\u3001\\u57df\\u540d\\u7b49\\u77e5\\u8bc6\\u4ea7\\u6743\\u7684\\uff1b<\\/p><p>\\uff084\\uff09\\u5176\\u4ed6\\u4e0d\\u6b63\\u5f53\\u7ade\\u4e89\\u6216\\u6270\\u4e71\\u5e02\\u573a\\u79e9\\u5e8f\\u7684\\u884c\\u4e3a\\u3002<\\/p><p>5.7 \\u6cd5\\u5f8b\\u6cd5\\u89c4\\u53ca\\u672c\\u534f\\u8bae\\u7ea6\\u5b9a\\u7684\\u5176\\u4ed6\\u4e49\\u52a1\\u3002<\\/p><h2><b>\\u516d\\u3001<\\/b><b>\\u6613\\u8d27\\u7f51<\\/b><b>\\u6743\\u5229\\u4e0e\\u4e49\\u52a1<\\/b><b><\\/b><\\/h2><p>6.1 \\u6613\\u8d27\\u7f51\\u6709\\u6743\\u6839\\u636e\\u56fd\\u5bb6\\u6cd5\\u5f8b\\u6cd5\\u89c4\\u53ca\\u81ea\\u8eab\\u7ecf\\u8425\\u9700\\u8981\\uff0c\\u5236\\u5b9a\\u3001\\u4fee\\u6539\\u3001\\u66f4\\u65b0\\u6613\\u8d27\\u7f51\\u89c4\\u5219\\u3001\\u516c\\u544a\\u3001\\u901a\\u77e5\\u7b49\\uff0c\\u5e76\\u901a\\u8fc7\\u6613\\u8d27\\u7f51\\u5b98\\u7f51\\u3001\\u4f1a\\u5458\\u8d26\\u53f7\\u901a\\u77e5\\u7b49\\u65b9\\u5f0f\\u5411\\u4f1a\\u5458\\u516c\\u793a\\u3002\\u516c\\u793a\\u671f\\u6ee1\\u540e\\uff0c\\u76f8\\u5173\\u89c4\\u5219\\u3001\\u516c\\u544a\\u3001\\u901a\\u77e5\\u7b49\\u5373\\u5bf9\\u4f1a\\u5458\\u4ea7\\u751f\\u7ea6\\u675f\\u529b\\u3002<\\/p><p>6.2 \\u6613\\u8d27\\u7f51\\u6709\\u6743\\u5bf9\\u4f1a\\u5458\\u6ce8\\u518c\\u4fe1\\u606f\\u3001\\u4f7f\\u7528\\u6613\\u8d27\\u7f51\\u670d\\u52a1\\u7684\\u884c\\u4e3a\\u8fdb\\u884c\\u76d1\\u7763\\u3001\\u68c0\\u67e5\\uff0c\\u5982\\u53d1\\u73b0\\u4f1a\\u5458\\u5b58\\u5728\\u8fdd\\u53cd\\u672c\\u534f\\u8bae\\u6216\\u5546\\u57ce\\u89c4\\u5219\\u7684\\u884c\\u4e3a\\uff0c\\u6709\\u6743\\u6839\\u636e\\u60c5\\u8282\\u8f7b\\u91cd\\u91c7\\u53d6\\u8b66\\u544a\\u3001\\u9650\\u5236\\u8d26\\u53f7\\u529f\\u80fd\\u3001\\u51bb\\u7ed3\\u8d26\\u53f7\\u3001\\u53d6\\u6d88\\u4f1a\\u5458\\u8d44\\u683c\\u3001\\u8ffd\\u7a76\\u6cd5\\u5f8b\\u8d23\\u4efb\\u7b49\\u63aa\\u65bd\\u3002<\\/p><p>6.3 \\u6613\\u8d27\\u7f51\\u6709\\u6743\\u6839\\u636e\\u5546\\u54c1\\u5e93\\u5b58\\u3001\\u5e02\\u573a\\u9700\\u6c42\\u3001\\u7ecf\\u8425\\u7b56\\u7565\\u7b49\\u60c5\\u51b5\\uff0c\\u8c03\\u6574\\u5546\\u54c1\\u4ef7\\u683c\\u3001\\u89c4\\u683c\\u3001\\u6b3e\\u5f0f\\u7b49\\u4fe1\\u606f\\uff0c\\u5e76\\u5728\\u6613\\u8d27\\u7f51\\u9875\\u9762\\u8fdb\\u884c\\u516c\\u793a\\u3002\\u4f1a\\u5458\\u4e0b\\u5355\\u540e\\uff0c\\u5982\\u5546\\u54c1\\u4ef7\\u683c\\u53d1\\u751f\\u8c03\\u6574\\uff0c\\u4ee5\\u4f1a\\u5458\\u4e0b\\u5355\\u65f6\\u7684\\u4ef7\\u683c\\u4e3a\\u51c6\\uff08\\u53e6\\u6709\\u7ea6\\u5b9a\\u7684\\u9664\\u5916\\uff09\\u3002<\\/p><p>6.4\\u6613\\u8d27\\u7f51\\u5e94\\u6309\\u7167\\u672c\\u534f\\u8bae\\u7ea6\\u5b9a\\u53ca\\u76f8\\u5173\\u6cd5\\u5f8b\\u6cd5\\u89c4\\u89c4\\u5b9a\\uff0c\\u4e3a\\u4f1a\\u5458\\u63d0\\u4f9b\\u7a33\\u5b9a\\u3001\\u5b89\\u5168\\u7684\\u670d\\u52a1\\u5e73\\u53f0\\uff0c\\u4fdd\\u969c\\u4f1a\\u5458\\u6b63\\u5e38\\u4f7f\\u7528\\u6613\\u8d27\\u7f51\\u670d\\u52a1\\u3002\\u5982\\u56e0\\u7cfb\\u7edf\\u7ef4\\u62a4\\u3001\\u5347\\u7ea7\\u3001\\u4e0d\\u53ef\\u6297\\u529b\\u7b49\\u539f\\u56e0\\u5bfc\\u81f4\\u6613\\u8d27\\u7f51\\u670d\\u52a1\\u6682\\u65f6\\u4e2d\\u65ad\\u7684\\uff0c\\u6613\\u8d27\\u7f51\\u5e94\\u53ca\\u65f6\\u901a\\u8fc7\\u9002\\u5f53\\u65b9\\u5f0f\\u901a\\u77e5\\u4f1a\\u5458\\uff0c\\u5e76\\u5c3d\\u5feb\\u6062\\u590d\\u670d\\u52a1\\u3002<\\/p><p>6.5 \\u6613\\u8d27\\u7f51\\u5e94\\u4fdd\\u62a4\\u4f1a\\u5458\\u7684\\u4e2a\\u4eba\\u4fe1\\u606f\\u5b89\\u5168\\uff0c\\u6309\\u7167\\u300a\\u4e2a\\u4eba\\u4fe1\\u606f\\u4fdd\\u62a4\\u6cd5\\u300b\\u7b49\\u76f8\\u5173\\u6cd5\\u5f8b\\u6cd5\\u89c4\\u89c4\\u5b9a\\uff0c\\u6536\\u96c6\\u3001\\u4f7f\\u7528\\u3001\\u5b58\\u50a8\\u3001\\u4f20\\u8f93\\u4f1a\\u5458\\u4e2a\\u4eba\\u4fe1\\u606f\\uff0c\\u4e0d\\u5f97\\u6cc4\\u9732\\u3001\\u51fa\\u552e\\u6216\\u975e\\u6cd5\\u63d0\\u4f9b\\u7ed9\\u7b2c\\u4e09\\u65b9\\uff08\\u6cd5\\u5f8b\\u6cd5\\u89c4\\u53e6\\u6709\\u89c4\\u5b9a\\u6216\\u4f1a\\u5458\\u540c\\u610f\\u7684\\u9664\\u5916\\uff09\\u3002\\u6613\\u8d27\\u7f51\\u5e94\\u91c7\\u53d6\\u52a0\\u5bc6\\u3001\\u9632\\u706b\\u5899\\u7b49\\u6280\\u672f\\u63aa\\u65bd\\u53ca\\u7ba1\\u7406\\u5236\\u5ea6\\uff0c\\u9632\\u6b62\\u4f1a\\u5458\\u4e2a\\u4eba\\u4fe1\\u606f\\u88ab\\u975e\\u6cd5\\u83b7\\u53d6\\u3001\\u4f7f\\u7528\\u6216\\u6cc4\\u9732\\u3002<\\/p><p>6.6 \\u6613\\u8d27\\u7f51\\u5e94\\u5efa\\u7acb\\u5065\\u5168\\u552e\\u540e\\u5ba2\\u670d\\u4f53\\u7cfb\\uff0c\\u53ca\\u65f6\\u5904\\u7406\\u4f1a\\u5458\\u7684\\u54a8\\u8be2\\u3001\\u6295\\u8bc9\\u3001\\u5efa\\u8bae\\u7b49\\u8bc9\\u6c42\\uff0c\\u4e3a\\u4f1a\\u5458\\u63d0\\u4f9b\\u4f18\\u8d28\\u7684\\u552e\\u540e\\u670d\\u52a1\\u3002<\\/p><p>6.7 \\u6613\\u8d27\\u7f51\\u5e94\\u6309\\u7167\\u56fd\\u5bb6\\u76f8\\u5173\\u89c4\\u5b9a\\uff0c\\u4e3a\\u4f1a\\u5458\\u5f00\\u5177\\u5408\\u6cd5\\u6709\\u6548\\u7684\\u53d1\\u7968\\uff08\\u4f1a\\u5458\\u6709\\u660e\\u786e\\u8981\\u6c42\\u7684\\u9664\\u5916\\uff09\\uff0c\\u4f1a\\u5458\\u53ef\\u5728\\u8ba2\\u5355\\u5b8c\\u6210\\u540e\\u6309\\u7167\\u6613\\u8d27\\u7f51\\u89c4\\u5b9a\\u7533\\u8bf7\\u5f00\\u5177\\u53d1\\u7968\\u3002<\\/p><p>6.8 \\u6cd5\\u5f8b\\u6cd5\\u89c4\\u53ca\\u672c\\u534f\\u8bae\\u7ea6\\u5b9a\\u7684\\u5176\\u4ed6\\u6743\\u5229\\u4e0e\\u4e49\\u52a1\\u3002<\\/p><h2><b>\\u4e03\\u3001\\u4e2a\\u4eba\\u4fe1\\u606f\\u4fdd\\u62a4<\\/b><b><\\/b><\\/h2><p>7.1 \\u6613\\u8d27\\u7f51\\u6536\\u96c6\\u4f1a\\u5458\\u4e2a\\u4eba\\u4fe1\\u606f\\u7684\\u8303\\u56f4\\u3001\\u65b9\\u5f0f\\u3001\\u7528\\u9014\\u7b49\\uff0c\\u8be6\\u89c1\\u6613\\u8d27\\u7f51\\u300a\\u9690\\u79c1\\u653f\\u7b56\\u300b\\u3002\\u300a\\u9690\\u79c1\\u653f\\u7b56\\u300b\\u662f\\u672c\\u534f\\u8bae\\u7684\\u7ec4\\u6210\\u90e8\\u5206\\uff0c\\u4e0e\\u672c\\u534f\\u8bae\\u5177\\u6709\\u540c\\u7b49\\u6cd5\\u5f8b\\u6548\\u529b\\u3002\\u4f1a\\u5458\\u6ce8\\u518c\\u5e76\\u4f7f\\u7528\\u6613\\u8d27\\u7f51\\u670d\\u52a1\\uff0c\\u5373\\u89c6\\u4e3a\\u5df2\\u540c\\u610f\\u5546\\u