INSERT INTO `eb_store_service_speechcraft` VALUES (1, 0, 0, '官网地址', 'http://www.crmeb.com', 0, 1605588484);
INSERT INTO `eb_store_service_speechcraft` VALUES (2, 0, 0, '论坛常见问题地址', 'http://bbs.crmeb.net/thread-4870-1-1.html', 0, 1605588562);
INSERT INTO `eb_store_service_speechcraft` VALUES (3, 0, 0, '接待开场白', '亲，您好，非常高兴为您服务了，有什么可以为您效劳的呢?', 0, 1605588671);
INSERT INTO `eb_store_service_speechcraft` VALUES (4, 0, 0, '帮助文档地址', 'http://help.crmeb.net', 0, 1605588676);
INSERT INTO `eb_store_service_speechcraft` VALUES (5, 0, 0, '论坛地址', 'http://bbs.crmeb.net', 0, 1605588694);
INSERT INTO `eb_store_service_speechcraft` VALUES (6, 0, 0, '放心拍', '亲，您看中的这款宝贝是有现货的呢，您可以放心拍哦O(_)O~', 0, 1605588719);
INSERT INTO `eb_store_service_speechcraft` VALUES (7, 0, 0, '发货时间', '亲，您拍下的42个小时内就可以为您安排发货的呢', 0, 1605588739);
INSERT INTO `eb_store_service_speechcraft` VALUES (8, 0, 0, ' 发什么快递', '亲，默认是发韵达快递哦，您这边可以收到韵达的货吗?韵达不到的地方我们可以为您安排发EMS，EMS是全国通达的，但是EMS是不包邮的呢，需要您补邮费10元，(发顺风的一样要补邮费20)', 0, 1605588758);
INSERT INTO `eb_store_service_speechcraft` VALUES (9, 0, 0, '什么时候到货?', '亲，一般韵达发货以后3天左右可以到货的呢，您收到货以后可以仔细检查一下，如有任何质量问题，7天内可以无条件退换货的，邮费也是外面承担。(顺风一般两天内到货，偏远地区会延迟到货时间)(EMS一般3-5天到货，偏远地区7天左右到货)\n', 0, 1605588778);
INSERT INTO `eb_store_service_speechcraft` VALUES (10, 0, 0, '可以便宜一点吗', '亲，非常抱歉，我们的定价已经是最低销售价格了呢，没有办法再优惠啦~~~', 0, 1605588794);
INSERT INTO `eb_store_service_speechcraft` VALUES (11, 0, 0, '质量问题', '亲，我们是商城正品，质量都是有保证的，您这边可以完全放心拍下哦。。。', 0, 1605588817);
INSERT INTO `eb_store_service_speechcraft` VALUES (12, 0, 0, '聊天结束', '亲，非常感谢您的惠顾我们这边会在第一时间为您安排发货的哦，请您耐心等待一下收货，如果有任何问题请您及时联系我们客服为您处理~~祝您购物愉快', 0, 1605588918);
INSERT INTO `eb_store_service_speechcraft` VALUES (13, 0, 0, '退货问题', '亲，7天内是可以无条件退换货的，质量问题您退换货单邮费都是我们为您承担，如果是非质量问题呢，您退回来的邮费以及我们给您换货发出的邮费是由您承担的哦', 0, 1605588943);
INSERT INTO `eb_store_service_speechcraft` VALUES (14, 0, 0, '单商户基础版演示', '演示后台：http://demo.crmeb.net/admin', 0, 1605589005);
INSERT INTO `eb_store_service_speechcraft` VALUES (15, 0, 0, '多商户演示', '演示后台：http://mer.crmeb.net/admin', 0, 1605589052);
INSERT INTO `eb_store_service_speechcraft` VALUES (16, 0, 0, '知识付费演示', '演示后台：http://zhishifufei.crmeb.net/admin', 0, 1605589105);
